/* A small isolated popover; site styles cannot turn it into a full-screen frame. */
export function installOnlineAdmin109(mp){
 const host=document.createElement('aside');host.id='bc-online109';host.hidden=true;host.setAttribute('aria-label','مدیریت کاربران آنلاین');
 const shadow=host.attachShadow({mode:'open'}),style=document.createElement('style');style.textContent=`
 :host{all:initial!important;position:fixed!important;left:max(14px,env(safe-area-inset-left))!important;bottom:max(86px,env(safe-area-inset-bottom))!important;top:auto!important;right:auto!important;width:auto!important;height:auto!important;padding:0!important;border:0!important;background:none!important;box-shadow:none!important;z-index:25000!important;direction:rtl!important;color:#edf9f6!important;font:13px/1.7 Vazirmatn,Tahoma,sans-serif!important;pointer-events:auto!important}
 :host([hidden]),[hidden]{display:none!important}*{box-sizing:border-box}button{font:inherit;cursor:pointer;color:inherit;border:1px solid #597c7d;border-radius:10px;background:#23434a;padding:7px 12px;min-height:38px}button:focus-visible{outline:3px solid #ffd391;outline-offset:3px}button:disabled{opacity:.55;cursor:wait}
 .trigger{display:flex;align-items:center;gap:9px;min-height:42px;border-radius:22px;background:#102932ed;box-shadow:0 3px 14px #0004;padding:7px 13px}.trigger svg{width:20px;height:20px;fill:none;stroke:currentColor;stroke-width:1.7}.count{min-width:23px;padding:0 5px;text-align:center;border-radius:8px;background:#416759;font-variant-numeric:tabular-nums}.arrow{font-size:10px;color:#a7c6bd}
 .drawer{position:absolute;left:0;bottom:52px;width:min(330px,calc(100vw - 28px));max-height:min(560px,calc(100dvh - 166px));overflow:auto;border:1px solid #537d7b;border-radius:16px;background:#10272ff7;box-shadow:0 12px 36px #0006;padding:14px;overscroll-behavior:contain}.heading{display:flex;align-items:center;justify-content:space-between;gap:10px;margin-bottom:4px}h3{font:700 14px/1.6 Vazirmatn,Tahoma,sans-serif;margin:0}.close{min-width:34px;min-height:34px;padding:0;font-size:22px;border-color:transparent;background:transparent}.hint{font-size:11px;color:#abc4c5;margin:0 0 12px}.row{padding:11px 0;border-top:1px solid #33515a}.name{display:block;font-size:13px;overflow-wrap:anywhere}.meta{font-size:11px;color:#abc4c5}.actions{display:flex;gap:7px;margin-top:8px}.actions button{font-size:11px;min-height:34px}.danger{background:#552b38;border-color:#975267}.empty{color:#abc4c5;font-size:12px;padding:10px 0}.error{color:#ffd1ab;white-space:pre-wrap;font-size:12px}.confirm{padding:10px;border:1px solid #bc9c6a;border-radius:10px;margin:8px 0}.confirm p{margin:0 0 8px}.confirm button{margin-left:6px}details{border-top:1px solid #33515a;margin-top:8px;padding-top:10px}summary{cursor:pointer;font-size:12px;color:#b6d1c8}
 @media(pointer:coarse),(max-width:700px){:host{bottom:max(190px,calc(env(safe-area-inset-bottom) + 178px))!important;left:12px!important}.drawer{width:min(310px,calc(100vw - 24px));max-height:max(80px,min(500px,55dvh,calc(100dvh - 260px)))}}
 `;shadow.append(style);
 const trigger=document.createElement('button');trigger.type='button';trigger.className='trigger';trigger.setAttribute('aria-expanded','false');trigger.setAttribute('aria-controls','online117-drawer');trigger.innerHTML='<svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="9" cy="7" r="3"/><path d="M3 21v-4a6 6 0 0 1 12 0v4M16 4a3 3 0 0 1 0 6m2 3a5 5 0 0 1 3 4v4"/></svg><span>آنلاین</span><b class="count">…</b><span class="arrow" aria-hidden="true">▲</span>';
 const drawer=document.createElement('section');drawer.id='online117-drawer';drawer.className='drawer';drawer.hidden=true;drawer.setAttribute('aria-label','کاربران آنلاین');
 const heading=document.createElement('div');heading.className='heading';const title=document.createElement('h3');title.textContent='کاربران آنلاین';const closeButton=document.createElement('button');closeButton.className='close';closeButton.type='button';closeButton.textContent='×';closeButton.setAttribute('aria-label','بستن فهرست');heading.append(title,closeButton);
 const hint=document.createElement('p');hint.className='hint';hint.textContent='مدیریت بازدیدکنندگان شهر برقتو';
 const error=document.createElement('p');error.className='error';error.setAttribute('role','status');const confirm=document.createElement('div');confirm.className='confirm';confirm.hidden=true;
 const list=document.createElement('div'),banned=document.createElement('details'),banTitle=document.createElement('summary'),bans=document.createElement('div');banned.append(banTitle,bans);drawer.append(heading,hint,error,confirm,list,banned);shadow.append(trigger,drawer);document.body.append(host);
 let busy=false,dead=false,signature='',timer;
 const num=n=>Number(n).toLocaleString('fa-IR'),button=(label,click,danger=false)=>{const b=document.createElement('button');b.type='button';b.textContent=label;b.onclick=click;b.className=danger?'danger':'';b.disabled=busy;return b;};
 function close(focus=false){drawer.hidden=true;trigger.setAttribute('aria-expanded','false');trigger.querySelector('.arrow').textContent='▲';confirm.hidden=true;if(focus)trigger.focus();}
 function ask(op,who){confirm.replaceChildren();const text=document.createElement('p');text.textContent=op==='unban'?`مسدودیت «${who.name}» برداشته شود؟`:op==='ban'?`«${who.name}» تا رفع مسدودیت وارد نشود؟`:`«${who.name}» خارج شود و تا ۶۰ ثانیه نتواند برگردد؟`;confirm.append(text,button('تأیید',async()=>{confirm.hidden=true;await refresh({op,...(op==='unban'?{subject:who.subject}:{target:who.id})});}),button('انصراف',()=>confirm.hidden=true));confirm.hidden=false;confirm.querySelector('button').focus();}
 function paint(data){trigger.querySelector('.count').textContent=num(data.count);title.textContent='کاربران آنلاین · '+num(data.count);const next=JSON.stringify([data.players,data.bans]);if(signature===next)return;signature=next;list.replaceChildren();bans.replaceChildren();
  for(const p of data.players){const row=document.createElement('div');row.className='row';const name=document.createElement('strong');name.className='name';name.textContent=p.name+(p.id===mp.id?' · شما':'');const meta=document.createElement('span');meta.className='meta';meta.textContent=(p.role==='admin'?'مدیر':'بازدیدکننده')+' · '+(/office/i.test(p.room)?'ساختمان برقتو':'شهر برقتو');row.append(name,meta);if(p.role!=='admin'&&p.id!==mp.id){const actions=document.createElement('div');actions.className='actions';actions.append(button('خروج موقت',()=>ask('kick',p)),button('مسدود کردن',()=>ask('ban',p),true));row.append(actions);}list.append(row);}
  if(!data.players.length){const p=document.createElement('p');p.className='empty';p.textContent='بازدیدکننده‌ای آنلاین نیست.';list.append(p);}banTitle.textContent='مسدودشده‌ها · '+num(data.bans.length);
  for(const p of data.bans){const row=document.createElement('div');row.className='row';const label=document.createElement('span');label.textContent=p.name+' ';row.append(label,button('رفع مسدودیت',()=>ask('unban',p)));bans.append(row);}
 }
 async function refresh(payload={op:'list'}){if(busy||dead||!mp.isAdmin)return;busy=true;error.textContent='';try{const data=await mp.request('bargheto_city_moderation109',payload);if(!dead){busy=false;paint(data);}}catch(e){error.textContent=e.message;trigger.querySelector('.count').textContent='؟';if(e.status===403)host.hidden=true;}finally{busy=false;}}
 trigger.onclick=()=>{document.exitPointerLock?.();drawer.hidden=!drawer.hidden;trigger.setAttribute('aria-expanded',String(!drawer.hidden));trigger.querySelector('.arrow').textContent=drawer.hidden?'▲':'▼';if(drawer.hidden)confirm.hidden=true;else{void refresh();closeButton.focus();}};closeButton.onclick=()=>close(true);
 const outside=e=>{if(!e.composedPath().includes(host)&&!drawer.hidden)close();};document.addEventListener('pointerdown',outside);
 for(const type of['pointerdown','mousedown','touchstart','click','keyup'])host.addEventListener(type,e=>e.stopPropagation());host.addEventListener('keydown',e=>{e.stopPropagation();if(e.code==='Escape'){e.preventDefault();close(true);}});
 function update(){if(mp.disposed){api.dispose();return;}const allowed=mp.isAdmin&&mp.joined&&!mp.immersive;host.hidden=!allowed;if(!allowed)close();if(!mp.isAdmin){signature='';list.replaceChildren();bans.replaceChildren();}else if(allowed&&!document.hidden)void refresh();}
 const api={host,shadow,drawer,trigger,refresh,dispose(){if(dead)return;dead=true;clearInterval(timer);document.removeEventListener('pointerdown',outside);host.remove();}};timer=setInterval(update,4000);queueMicrotask(update);return api;
}
